/**
 * Regenerate src/ide/assets.gen.ts from the IDE HTML. Run after editing
 * src/ide/index.html:
 *
 *   bun run scripts/gen-ide-assets.ts
 */
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = join(import.meta.dir, "..");
const html = readFileSync(join(root, "src/ide/index.html"), "utf8");

const out =
  "// Generated by scripts/gen-ide-assets.ts — embedded UI for `goat ide`.\n" +
  "// Edit src/ide/index.html, then re-run the generator. Do not hand-edit.\n" +
  "export const UI_HTML = " + JSON.stringify(html) + ";\n";

writeFileSync(join(root, "src/ide/assets.gen.ts"), out, "utf8");
console.log(`wrote src/ide/assets.gen.ts (${out.length} bytes)`);
